string[] inputs = { "42", "abc", "99999999999", "-5" };

foreach (var input in inputs)
{
    try
    {
        int value = Parser.Positive(input);
        Console.WriteLine($"{input}: accepted {value}");
    }
    catch (ArgumentException ex)
    {
        Console.WriteLine($"{input}: rejected, {ex.Message}");
    }
    catch (Exception ex) when (ex is FormatException
                               or OverflowException)
    {
        Console.WriteLine($"{input}: not an int ({ex.GetType().Name})");
    }
    finally
    {
        Console.WriteLine("  checked");
    }
}

if (int.TryParse("17", out int n))
    Console.WriteLine($"TryParse gave {n} without any exception");

static class Parser
{
    public static int Positive(string text)
    {
        int value = int.Parse(text);   // may throw
        if (value < 1)
            throw new ArgumentException("must be at least 1");
        return value;
    }
}

