// One order line, like "APPLE-01, 3": a stock code (SKU) and a quantity.
class Order
{
    public string Sku { get; }
    public int Quantity { get; }

    public Order(string sku, int quantity)
    {
        Sku = sku;
        Quantity = quantity;
    }
}

// Thrown for a line that can't be imported. Finished: use it as it is.
class ImportException : Exception
{
    public int LineNumber { get; }

    public ImportException(int lineNumber, string message,
                           Exception inner = null)
        : base($"Line {lineNumber}: {message}", inner)
    {
        LineNumber = lineNumber;
    }
}

static class Importer
{
    // Turns one line into an Order.
    // Should throw an ImportException (with the line number) for any bad line.
    public static Order ParseLine(string line, int lineNumber)
    {
        string[] parts = line.Split(',');
        if (parts.Length != 2)
            throw new ImportException(lineNumber, $"expected 2 fields, found {parts.Length}");

        string sku = parts[0].Trim();
        string text = parts[1].Trim();
        int quantity;
        try
        {
            quantity = int.Parse(text);
        }
        catch (Exception ex) when (ex is FormatException or OverflowException)
        {
            throw new ImportException(lineNumber, $"\"{text}\" is not a valid quantity", ex);
        }

        if (quantity < 1)
            throw new ImportException(lineNumber, "quantity must be at least 1");
        return new Order(sku, quantity);
    }

    // Imports every good line. Should skip each bad line, add its message
    // to errors, and carry on with the next line.
    public static List<Order> ImportAll(string[] lines, List<string> errors)
    {
        var orders = new List<Order>();
        for (int i = 0; i < lines.Length; i++)
        {
            try
            {
                orders.Add(ParseLine(lines[i], i + 1));
            }
            catch (ImportException ex)
            {
                errors.Add(ex.Message);
            }
        }
        return orders;
    }
}

